void scsi_iopool_destroy ( struct scsi_iopool * iopl ) { struct scsi_runq sleepers = TAILQ_HEAD_INITIALIZER ( sleepers ) ; mtx_enter ( & iopl -> mtx ) ; while ( ( ioh = TAILQ_FIRST ( & iopl -> queue ) ) != NULL ) { TAILQ_REMOVE ( & iopl -> queue , ioh , q_entry ) ; ioh -> q_state = RUNQ_IDLE ; if ( ioh -> handler == scsi_io_get_done ) { TAILQ_INSERT_TAIL ( & sleepers , ioh , q_entry ) ; } else { panic ( "scsi_iopool_destroy: scsi_iohandler on pool" ) ; } } mtx_leave ( & iopl -> mtx ) ; while ( ( ioh = TAILQ_FIRST ( & sleepers ) ) != NULL ) { TAILQ_REMOVE ( & sleepers , ioh , q_entry ) ; ioh -> handler ( ioh -> cookie , NULL ) ; } } 